def RightEquivariant (n : ℕ) (F : QuaternionMatrix2 → BinaryForm n) : Prop :=
  ∀ g, IsSp11 g → ∀ a b : ℍ, Quaternion.normSq a = 1 → Quaternion.normSq b = 1 →
    F (g * compactMatrix a b) = polynomialRepresentation n (quaternionMatrix b⁻¹) (F g)

