def quaternionMatrix (q : ℍ) : Matrix2 :=
  !![ (q.re : ℂ) + Complex.I * q.imI, (q.imJ : ℂ) +
      Complex.I * q.imK;
      -(q.imJ : ℂ) + Complex.I * q.imK, (q.re : ℂ) -
          Complex.I * q.imI ]

declarations.source_text:
def quaternionMatrix (q : ℍ) : Matrix2 :=
  !![ (q.re : ℂ) + Complex.I * q.imI, (q.imJ : ℂ) + Complex.I * q.imK;
      -(q.imJ : ℂ) + Complex.I * q.imK, (q.re : ℂ) - Complex.I * q.imI ]

def weakSpinorIsometry (m : ℕ) (hm : 1 ≤ m) :
    WeakBallSpace (m+1) (by omega) ≃ₗᵢ[ℂ] weakRowKernel m hm :=
  (spinorL2Isometry m).submoduleMap (weakKernel (m+1) (by omega))

