def weightedBallMeasure (n : ℕ) : Measure ℍ :=
  (volume.restrict Ball).withDensity (fun q =>
      ENNReal.ofReal (ballDensity n q))

def ballRepresentation (n : ℕ) (γ : QuaternionMatrix2)
    (f : ℍ → BinaryForm n) : ℍ → BinaryForm n :=
  ballAction n (signatureAdjoint γ) f

def rowBallRepresentation (m : ℕ) (g :
    QuaternionMatrix2) := rowBallAction m
    (signatureAdjoint g)

