def regularCoefficient (n : ℕ) (hn : 2 ≤ n) (v : BinaryForm n)
    (f : WeakBallSpace n hn) (g : Sp11) : ℂ :=
  inner ℂ (constantRegularIsometry n hn v) (regularRepresentation n hn g⁻¹ f)

