def regularPartialEvaluation (n : ℕ) (hn : 2 ≤ n) (vs : List ℍ) (a : ℍ) (ha : a ∈ Ball) :
    WeakBallSpace n hn →L[ℂ] BinaryForm n :=
  (testIntegralCLM n hn (partialAdjointTest vs (interiorKernelTest a ha))).comp (weakKernel n hn).subtypeL

