def normalizedGroupHaar : Measure Sp11 :=
  Measure.map groupFromBallCoordinates
      (ballInvariantMeasure.prod compactHaar)

def algebraMulCLM : M →L[ℝ] M →L[ℝ] M :=
  (LinearMap.toContinuousLinearMap.toLinearMap.comp
      (LinearMap.mul ℝ M)).toContinuousLinearMap
